-- Header INSERT stamps server time; move only the synthetic expired fixture.
alter table public.despachos disable trigger proteger_movimiento_b3;
update public.despachos set creado_en=clock_timestamp()-interval '10 minutes 0.001 seconds' where id='76000000-0000-0000-0000-000000000002';
alter table public.despachos enable trigger proteger_movimiento_b3;
create temporary table resultado_hu26(valor jsonb); grant all on resultado_hu26 to authenticated;
