select throws_ok($q$select public.ajustar_despacho('76000000-0000-0000-0000-000000000003','[{"producto_id": "40000000-0000-0000-0000-000000000001", "cantidad": 3}]'::jsonb,'77000000-0000-0000-0000-000000000003')$q$,'P0001','El despacho está anulado','Cancelled dispatch denied');
