select throws_ok($q$select public.ajustar_despacho('76000000-0000-0000-0000-000000000001','{}'::jsonb,'77000000-0000-0000-0000-000000000008')$q$,'P0001','Agrega al menos un producto al despacho.','Non-array payload denied');
